const fs=require('node:fs/promises'),assert=require('node:assert/strict');
(async()=>{const b=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const report={checks:[]};try{const p=await b.newPage({viewport:{width:1470,height:900}});await p.goto('http://localhost:5173/');await p.getByLabel('Import file into library',{exact:true}).setInputFiles('tests/fixtures/safari-preview/source.vdoc.json');await p.waitForFunction(()=>window.vdoc);const before=await p.evaluate(()=>window.vdoc.snapshot().document);let current=100;for(const zoom of [75,100,125]){await p.getByRole('button',{name:current+'%',exact:true}).click();await p.getByRole('menuitem',{name:zoom+'%',exact:true}).click();current=zoom;await p.waitForTimeout(200);for(const where of ['middle','end']){await p.evaluate(where=>{const t=document.querySelector('.document-editor table').getBoundingClientRect(),c=document.querySelector('.canvas-scroll'),top=document.querySelector('.paragraph-ruler').getBoundingClientRect().bottom;c.scrollTop+=where==='middle'?t.top+t.height/2-top:t.bottom-top-120},where);await p.waitForTimeout(150);const hits=await p.locator('.document-editor .vdoc-pinned-row > th').evaluateAll(cells=>cells.map(c=>{const r=c.getBoundingClientRect();return [.25,.5,.75].map(x=>document.elementFromPoint(r.left+r.width*x,r.top+r.height/2)?.closest('td,th')===c)}));assert.equal(hits.length,2);assert(hits.flat().every(Boolean));assert.deepEqual(await p.evaluate(()=>window.vdoc.snapshot().document),before);report.checks.push({zoom,where,hits});}}await p.emulateMedia({media:'print'});const transforms=await p.locator('.document-editor .vdoc-pinned-row > th').evaluateAll(cells=>cells.map(c=>getComputedStyle(c).transform));assert(transforms.every(t=>t==='none'));report.printTransforms=transforms;report.browser=b.version();report.fullJSONUnchanged=true;await fs.writeFile('tests/fixtures/safari-pinned-paint-20261010/chromium.json',JSON.stringify(report,null,2));console.log('6 Chrome paint/hit-test cases and print transform reset passed');}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
